set local standard_conforming_strings=on;
insert into public.sources(book_id,id,url,label) select 'proust',p.id,p.url,p.label from jsonb_to_recordset('[{"id":"85c1efefaabed0d6582b95564f908ab55e8efaf8047f083aa2d64762c71f303f","url":"https://fr.wikisource.org/wiki/Du_c%C3%B4t%C3%A9_de_chez_Swann%2FPartie_1","label":"Du côté de chez Swann · Combray · Gallimard, 1946"},{"id":"51281716b6bd3df8e74a09e209be5289848829a66cc78dce4071b6a6f47cd259","url":"https://fr.wikisource.org/wiki/%C3%80_l%E2%80%99ombre_des_jeunes_filles_en_fleurs%2FDeuxi%C3%A8me_partie","label":"À l’ombre des jeunes filles en fleurs · II · Gallimard, 1919, t. 4"},{"id":"136b6368ee97132b0dd5f0bf98c5a3ba1f34b0e33adcbe7cbebf61bf5ef1a479","url":"https://fr.wikisource.org/wiki/%C3%80_l%E2%80%99ombre_des_jeunes_filles_en_fleurs%2FTroisi%C3%A8me_partie","label":"À l’ombre des jeunes filles en fleurs · III · Gallimard, 1919, t. 5"},{"id":"27e2dc5b1c2a726c08e1f623790bb63fa161bf9cfa3761de9957f662a774e5ce","url":"https://fr.wikisource.org/wiki/Sodome_et_Gomorrhe%2FPartie_2_-_chapitre_1","label":"Sodome et Gomorrhe · deuxième partie, chapitre I · Gallimard, 1924, t. 9"},{"id":"4552694737cea5621aa94e5a4d698772fc0bb8ca4bcd4fab163ce7e1f1fc5253","url":"https://fr.wikisource.org/wiki/Le_Temps_retrouv%C3%A9%2FI","label":"Le Temps retrouvé · I · Gallimard, 1927, t. 14"}]'::jsonb) as p(id text,url text,label text) on conflict(book_id,id) do nothing;
do $review$
declare changed integer;
begin
with patch as(select * from jsonb_to_recordset('[{"id":"1:core:leonie:original","old_quote":"Et tout d’un coup le souvenir m’est apparu. Ce goût, c’était celui du petit morceau de madeleine que le dimanche matin à Combray (parce que ce jour-là je ne sortais pas avant l’heure de la messe), quand j’allais lui dire bonjour dans sa chambre, ma tante Léonie m’offrait après l’avoir trempé dans son infusion de thé ou de tilleul. La vue de la petite madeleine ne m’avait rien rappelé avant que je n’y eusse goûté ; peut-être parce que, en ayant souvent aperçu depuis, sans en manger, sur les tablettes des pâtissiers, leur image avait quitté ces jours de Combray pour se lier à d’autres plus récents ; peut-être parce […]","quote":"Et tout d’un coup le souvenir m’est apparu. Ce goût, c’était celui du petit morceau de madeleine que le dimanche matin à Combray (parce que ce jour-là je ne sortais pas avant l’heure de la messe), quand j’allais lui dire bonjour dans sa chambre, ma tante Léonie m’offrait après l’avoir trempé dans son infusion de thé ou de tilleul.","attribution":"Marcel Proust · Du côté de chez Swann · Combray · Gallimard, 1946 · position 105771–106103 (texte normalisé)","text_source_id":"85c1efefaabed0d6582b95564f908ab55e8efaf8047f083aa2d64762c71f303f","metadata":{"highlightTerms":["sa chambre","ma tante Léonie"],"highlightMode":"explicit","sourceStart":105771,"sourceEnd":106103,"sourceNormalization":"whitespace","sourceCorpus":"proust-85c1efefaabe.txt","quotationReview":"2026-10-15"}},{"id":"1:core:church:original","old_quote":"Combray, de loin, à dix lieues à la ronde, vu du chemin de fer quand nous y arrivions la dernière semaine avant Pâques, ce n’était qu’une église résumant la ville, la représentant, parlant d’elle et pour elle aux lointains, et, quand on approchait, tenant serrés autour de sa haute mante sombre, en plein champ, contre le vent, comme une pastoure ses brebis, les dos laineux et gris des maisons rassemblées qu’un reste de remparts du moyen âge cernait çà et là d’un trait aussi parfaitement circulaire qu’une petite ville dans un tableau de primitif. À l’habiter, Combray était un peu triste, comme ses rues dont les […]","quote":"je m’avançais dans l’église, quand nous gagnions nos chaises, comme dans une vallée visitée des fées, où le paysan s’émerveille de voir dans un rocher, dans un arbre, dans une mare, la trace palpable de leur passage surnaturel ;","attribution":"Marcel Proust · Du côté de chez Swann · Combray · Gallimard, 1946 · position 139097–139325 (texte normalisé)","text_source_id":"85c1efefaabed0d6582b95564f908ab55e8efaf8047f083aa2d64762c71f303f","metadata":{"highlightTerms":["l’église"],"highlightMode":"explicit","sourceStart":139097,"sourceEnd":139325,"sourceNormalization":"whitespace","sourceCorpus":"proust-85c1efefaabe.txt","quotationReview":"2026-10-15"}},{"id":"1:core:garden:original","old_quote":"Puis renaissait le souvenir d’une nouvelle attitude ; le mur filait dans une autre direction : j’étais dans ma chambre chez M de Saint-Loup, à la campagne. Mon Dieu ! Il est au moins dix heures, on doit avoir fini de dîner ! J’aurai trop prolongé la sieste que je fais tous les soirs en rentrant de ma promenade avec M de Saint-Loup, avant d’endosser mon habit. Car bien des années ont passé depuis Combray, où, dans nos retours les plus tardifs, c’étaient les reflets rouges du couchant que je voyais sur le vitrage de ma fenêtre. C’est un autre genre de vie qu’on mène à Tansonville, chez M de Saint-Loup, un autre […]","quote":"mon grand-père m’appelant et me désignant la haie de Tansonville, me dit : « Toi qui aimes les aubépines, regarde un peu cette épine rose ; est-elle jolie ! »","attribution":"Marcel Proust · Du côté de chez Swann · Combray · Gallimard, 1946 · position 322234–322392 (texte normalisé)","text_source_id":"85c1efefaabed0d6582b95564f908ab55e8efaf8047f083aa2d64762c71f303f","metadata":{"highlightTerms":["la haie de Tansonville"],"highlightMode":"explicit","sourceStart":322234,"sourceEnd":322392,"sourceNormalization":"whitespace","sourceCorpus":"proust-85c1efefaabe.txt","quotationReview":"2026-10-15"}},{"id":"2:core:hotel:original","old_quote":"Dans le petit chemin de fer d’intérêt local qui devait nous conduire à Balbec-Plage, je retrouvai ma grand’mère mais l’y retrouvai seule — car elle avait imaginé de faire partir avant elle, pour que tout fût préparé d’avance (mais lui ayant donné un renseignement faux n’avait réussi qu’à faire partir dans une mauvaise direction), Françoise qui en ce moment sans s’en douter filait à toute vitesse sur Nantes et se réveillerait peut-être à Bordeaux. À peine fus-je assis dans le wagon rempli par la lumière fugitive du couchant et par la chaleur persistante de l’après-midi (la première, hélas ! me permettant de voir […]","quote":"Mais combien ma souffrance s’aggrava quand nous eûmes débarqué dans le hall du Grand-Hôtel de Balbec, en face de l’escalier monumental qui imitait le marbre, et pendant que ma grand’mère, sans souci d’accroître l’hostilité et le mépris des étrangers au milieu desquels nous allions vivre, discutait les « conditions » avec le directeur,","attribution":"Marcel Proust · À l’ombre des jeunes filles en fleurs · II · Gallimard, 1919, t. 4 · position 140577–140913 (texte normalisé)","text_source_id":"51281716b6bd3df8e74a09e209be5289848829a66cc78dce4071b6a6f47cd259","metadata":{"highlightTerms":["hall du Grand-Hôtel de Balbec"],"highlightMode":"explicit","sourceStart":140577,"sourceEnd":140913,"sourceNormalization":"whitespace","sourceCorpus":"proust-51281716b6bd.txt","quotationReview":"2026-10-15"}},{"id":"2:core:promenade:original","old_quote":"J’étais arrivé à une presque complète indifférence à l’égard de Gilberte, quand deux ans plus tard je partis avec ma grand’mère pour Balbec. Quand je subissais le charme d’un visage nouveau, quand c’était à l’aide d’une autre jeune fille que j’espérais connaître les cathédrales gothiques, les palais et les jardins de l’Italie, je me disais tristement que notre amour, en tant qu’il est l’amour d’une certaine créature, n’est peut-être pas quelque chose de bien réel, puisque si des associations de rêveries agréables ou douloureuses peuvent le lier pendant quelque temps à une femme jusqu’à nous faire penser qu’il a […]","quote":"Seul, je restai simplement devant le Grand-Hôtel à attendre le moment d’aller retrouver ma grand’mère, quand, presque encore à l’extrémité de la digue où elles faisaient mouvoir une tache singulière, je vis s’avancer cinq ou six fillettes, aussi différentes, par l’aspect et par les façons, de toutes les personnes auxquelles on était accoutumé à Balbec, qu’aurait pu l’être, débarquée on ne sait d’où, une bande de mouettes qui exécute à pas comptés sur la plage, — les retardataires rattrapant les autres en voletant — une promenade dont le but semble aussi obscur aux baigneurs qu’elles ne paraissent pas voir, que clairement déterminé pour leur esprit d’oiseaux.","attribution":"Marcel Proust · À l’ombre des jeunes filles en fleurs · III · Gallimard, 1919, t. 5 · position 48388–49054 (texte normalisé)","text_source_id":"136b6368ee97132b0dd5f0bf98c5a3ba1f34b0e33adcbe7cbebf61bf5ef1a479","metadata":{"highlightTerms":["la digue"],"highlightMode":"explicit","sourceStart":48388,"sourceEnd":49054,"sourceNormalization":"whitespace","sourceCorpus":"proust-136b6368ee97.txt","quotationReview":"2026-10-15"}},{"id":"4:core:hotel:original","old_quote":"Pendant que maman lisait sur la plage je restais seul dans ma chambre. Je me rappelais les derniers temps de la vie de ma grand’mère et tout ce qui se rapportait à eux, la porte de l’escalier qui était maintenue ouverte quand nous étions sortis pour sa dernière promenade. En contraste avec tout cela, le reste du monde semblait à peine réel et ma souffrance l’empoisonnait tout entier. Enfin ma mère exigea que je sortisse. Mais, à chaque pas, quelque aspect oublié du Casino, de la rue où en l’attendant, le premier soir, j’étais allé jusqu’au monument de Duguay-Trouin, m’empêchait, comme un vent contre lequel on ne […]","quote":"je pouvais me demander si je pénétrais dans le grand hôtel de Balbec ou dans le temple de Salomon. Je remontais directement à ma chambre.","attribution":"Marcel Proust · Sodome et Gomorrhe · deuxième partie, chapitre I · Gallimard, 1924, t. 9 · position 333030–333167 (texte normalisé)","text_source_id":"27e2dc5b1c2a726c08e1f623790bb63fa161bf9cfa3761de9957f662a774e5ce","metadata":{"highlightTerms":["grand hôtel de Balbec","ma chambre"],"highlightMode":"explicit","sourceStart":333030,"sourceEnd":333167,"sourceNormalization":"whitespace","sourceCorpus":"proust-27e2dc5b1c2a.txt","quotationReview":"2026-10-15"}},{"id":"4:core:promenade:original","old_quote":"Je levai la tête et vis le duc de Guermantes qui venait à nous. « Pardon de vous déranger, mes enfants. Mon petit, dit-il en s’adressant à moi, je suis délégué auprès de vous par Oriane. Marie et Gilbert lui ont demandé de rester à souper à leur table avec cinq ou six personnes seulement : la princesse de Hesse, M de Ligne, M de Tarente, M de Chevreuse, la duchesse d’Arenberg. Malheureusement, nous ne pouvons pas rester, parce que nous allons à une espèce de petite redoute. » J’écoutais, mais chaque fois que nous avons quelque chose à faire à un moment déterminé, nous chargeons nous-mêmes un certain personnage […]","quote":"Elle voulut descendre sur la digue voir cette plage dont ma grand’mère lui parlait tous les jours en lui écrivant. Tenant à la main l’« en tous cas » de sa mère, je la vis de la fenêtre s’avancer toute noire, à pas timides, pieux, sur le sable que des pieds chéris avaient foulé avant elle, et elle avait l’air d’aller à la recherche d’une morte que les flots devaient ramener.","attribution":"Marcel Proust · Sodome et Gomorrhe · deuxième partie, chapitre I · Gallimard, 1924, t. 9 · position 322363–322740 (texte normalisé)","text_source_id":"27e2dc5b1c2a726c08e1f623790bb63fa161bf9cfa3761de9957f662a774e5ce","metadata":{"highlightTerms":["la digue","cette plage","le sable"],"highlightMode":"explicit","sourceStart":322363,"sourceEnd":322740,"sourceNormalization":"whitespace","sourceCorpus":"proust-27e2dc5b1c2a.txt","quotationReview":"2026-10-15"}},{"id":"7:core:garden:original","old_quote":"Toute la journée, dans cette demeure de Tansonville un peu trop campagne, qui n’avait l’air que d’un lieu de sieste entre deux promenades ou pendant l’averse, une de ces demeures où chaque salon a l’air d’un cabinet de verdure, et où sur la tenture des chambres, les roses du jardin dans l’une, les oiseaux des arbres dans l’autre, vous ont rejoints et vous tiennent compagnie — isolés du moins — car c’étaient de vieilles tentures où chaque rose était assez séparée pour qu’on eût pu, si elle avait été vivante, la cueillir, chaque oiseau le mettre en cage et l’apprivoiser, sans rien de ces grandes décorations des […]","quote":"Une fois, que j’avais quitté Gilberte assez tôt, je m’éveillai au milieu de la nuit dans la chambre de Tansonville, et encore à demi endormi j’appelai : « Albertine ».","attribution":"Marcel Proust · Le Temps retrouvé · I · Gallimard, 1927, t. 14 · position 3798–3965 (texte normalisé)","text_source_id":"4552694737cea5621aa94e5a4d698772fc0bb8ca4bcd4fab163ce7e1f1fc5253","metadata":{"highlightTerms":["la chambre de Tansonville"],"highlightMode":"explicit","sourceStart":3798,"sourceEnd":3965,"sourceNormalization":"whitespace","sourceCorpus":"proust-4552694737ce.txt","quotationReview":"2026-10-15"}}]'::jsonb) as p(id text,old_quote text,quote text,attribution text,text_source_id text,metadata jsonb))
update public.excerpts q set quote=p.quote,attribution=p.attribution,text_source_id=p.text_source_id,metadata=q.metadata||p.metadata from patch p where q.book_id='proust' and q.id=p.id and(q.quote=p.old_quote or q.quote=p.quote);
get diagnostics changed=row_count;
if changed<>8 then raise exception 'Proust quotation conflict: %',changed;end if;
end $review$;
update public.books set metadata=jsonb_set(jsonb_set(coalesce(metadata,'{}'::jsonb),'{illustratedView}','{"version":1,"width":1586,"height":992,"checked":"2026-10-15","offerGeography":true,"preferIllustratedAnchors":true,"labels":{"it":{"view":"Vista","area":"Combray e Balbec","back":"Torna alla veduta","geographic":"Mappa geografica dei modelli reali","caption":"Veduta interpretativa · non in scala","alt":"Vedute aeree realistiche di Combray e della stazione balneare di Balbec.","notice":"Combray e Balbec sono luoghi letterari. Queste vedute interpretano edifici, paesaggio e distanze; non riproducono una pianta documentata. La mappa geografica conserva separatamente i modelli di Illiers-Combray e Cabourg.","method":"Il punto sull’immagine indica un elemento della ricostruzione, senza coordinate terrestri. La citazione documenta la scena; la disposizione degli edifici è figurativa.","reference":"Un riferimento geografico nel testo originale.","empty":"Nessun luogo visibile in questa veduta per la sezione e i filtri scelti."},"en":{"view":"View","area":"Combray and Balbec","back":"Back to illustration","geographic":"Geographic map of real models","caption":"Interpretative view · not to scale","alt":"Realistic aerial views of Combray and the seaside resort of Balbec.","notice":"Combray and Balbec are literary places. These views interpret buildings, landscape and distances; they do not reproduce a documented plan. The geographic map separately retains the models in Illiers-Combray and Cabourg.","method":"An image marker identifies an element of the reconstruction, without terrestrial coordinates. The quotation documents the scene; the arrangement of buildings is interpretative.","reference":"A geographical reference in the original text.","empty":"No visible places in this view for the selected section and filters."},"fr":{"view":"Vue","area":"Combray et Balbec","back":"Retour à la vue illustrée","geographic":"Carte géographique des modèles réels","caption":"Vue interprétative · sans échelle","alt":"Vues aériennes réalistes de Combray et de la station balnéaire de Balbec.","notice":"Combray et Balbec sont des lieux littéraires. Ces vues interprètent bâtiments, paysages et distances ; elles ne reproduisent pas un plan documenté. La carte géographique conserve séparément les modèles d’Illiers-Combray et de Cabourg.","method":"Le repère sur l’image désigne un élément de la reconstitution, sans coordonnées terrestres. La citation atteste la scène ; la disposition des bâtiments est figurative.","reference":"Une référence géographique dans le texte original.","empty":"Aucun lieu visible dans cette vue pour la section et les filtres choisis."},"es":{"view":"Vista","area":"Combray y Balbec","back":"Volver a la ilustración","geographic":"Mapa geográfico de los modelos reales","caption":"Vista interpretativa · sin escala","alt":"Vistas aéreas realistas de Combray y de la estación balnearia de Balbec.","notice":"Combray y Balbec son lugares literarios. Estas vistas interpretan edificios, paisaje y distancias; no reproducen un plano documentado. El mapa geográfico conserva por separado los modelos de Illiers-Combray y Cabourg.","method":"El marcador sobre la imagen señala un elemento de la reconstrucción, sin coordenadas terrestres. La cita documenta la escena; la disposición de los edificios es figurativa.","reference":"Una referencia geográfica en el texto original.","empty":"No hay lugares visibles en esta vista para la sección y los filtros elegidos."}},"sceneNotes":{"it":{"1:leonie":"Il ricordo della madeleine rievoca la visita mattutina nella camera di zia Léonie.","1:church":"Il narratore avanza nella chiesa di Saint-Hilaire verso i posti della famiglia; l’interno intreccia esperienza infantile e memoria storica.","1:garden":"Durante la passeggiata il nonno indica al narratore il biancospino rosa della siepe di Tansonville. Il punto rappresenta la proprietà e il suo margine, senza fissare il percorso.","2:hotel":"Il narratore arriva con la nonna nel salone del Grand-Hôtel di Balbec, dove lei tratta le condizioni del soggiorno.","2:promenade":"Davanti al Grand-Hôtel, il narratore vede avvicinarsi lungo la diga il gruppo delle ragazze.","4:hotel":"Nel secondo soggiorno a Balbec il narratore torna nella sua camera d’albergo, immerso nel lutto per la nonna.","4:promenade":"La madre scende sulla diga e sulla spiaggia seguendo il ricordo della nonna; il narratore la osserva dalla finestra.","7:garden":"Ospite a Tansonville, il narratore si sveglia nella notte e chiama Albertine. Il punto comprende la dimora e il parco, non una posizione della camera."},"en":{"1:leonie":"The madeleine recalls the morning visit to Aunt Léonie’s room.","1:church":"The narrator walks into Saint-Hilaire towards the family’s chairs; childhood experience meets historical memory.","1:garden":"During a walk, his grandfather points out the pink hawthorn in the Tansonville hedge. The marker represents the estate and its boundary, without fixing their route.","2:hotel":"The narrator arrives with his grandmother in the Grand-Hôtel hall at Balbec, where she negotiates their stay.","2:promenade":"Outside the Grand-Hôtel, the narrator sees the group of girls approaching along the esplanade.","4:hotel":"During his second Balbec stay, the narrator returns to his hotel room, absorbed in grief for his grandmother.","4:promenade":"His mother walks onto the esplanade and beach in his grandmother’s footsteps; the narrator watches from the window.","7:garden":"Staying at Tansonville, the narrator wakes at night and calls Albertine. The marker includes the house and park, without locating his room."},"fr":{"1:leonie":"La madeleine rappelle la visite matinale dans la chambre de tante Léonie.","1:church":"Le narrateur avance dans Saint-Hilaire vers les chaises de la famille ; l’expérience enfantine rencontre la mémoire historique.","1:garden":"Pendant la promenade, son grand-père lui montre l’épine rose de la haie de Tansonville. Le repère représente le domaine et sa limite, sans fixer leur parcours.","2:hotel":"Le narrateur arrive avec sa grand-mère dans le hall du Grand-Hôtel de Balbec, où elle négocie leur séjour.","2:promenade":"Devant le Grand-Hôtel, le narrateur voit approcher sur la digue le groupe des jeunes filles.","4:hotel":"Lors de son second séjour à Balbec, le narrateur regagne sa chambre, absorbé par le deuil de sa grand-mère.","4:promenade":"Sa mère descend sur la digue et la plage sur les traces de sa grand-mère ; le narrateur l’observe de la fenêtre.","7:garden":"Hôte à Tansonville, le narrateur se réveille la nuit et appelle Albertine. Le repère comprend la demeure et le parc, sans situer sa chambre."},"es":{"1:leonie":"La magdalena evoca la visita matinal al cuarto de la tía Léonie.","1:church":"El narrador avanza por Saint-Hilaire hacia los asientos de la familia; la experiencia infantil se une a la memoria histórica.","1:garden":"Durante el paseo, su abuelo le muestra el espino rosa del seto de Tansonville. El marcador representa la propiedad y su límite, sin fijar el recorrido.","2:hotel":"El narrador llega con su abuela al vestíbulo del Grand-Hôtel de Balbec, donde ella negocia la estancia.","2:promenade":"Frente al Grand-Hôtel, el narrador ve acercarse por el paseo al grupo de muchachas.","4:hotel":"Durante su segunda estancia en Balbec, el narrador vuelve a su habitación, sumido en el duelo por su abuela.","4:promenade":"Su madre baja al paseo y a la playa tras las huellas de su abuela; el narrador la observa desde la ventana.","7:garden":"Huésped en Tansonville, el narrador se despierta de noche y llama a Albertine. El marcador comprende la casa y el parque, sin situar su cuarto."}},"names":{"en":{},"it":{},"fr":{},"es":{}},"notes":{"en":{},"it":{},"fr":{},"es":{}},"geographicFirstSections":[3,5,6],"sectionViews":{"1":0,"2":1,"3":0,"4":1,"5":0,"6":0,"7":0},"placeOrder":["leonie","church","garden","hotel","promenade"],"views":[{"id":"combray","image":"images/proust/combray-panorama.png","names":{"it":"Combray","en":"Combray","fr":"Combray","es":"Combray"},"positions":{"leonie":[0.29,0.66],"church":[0.32,0.27],"garden":[0.82,0.23]}},{"id":"balbec","image":"images/proust/balbec-panorama.png","names":{"it":"Balbec","en":"Balbec","fr":"Balbec","es":"Balbec"},"positions":{"hotel":[0.36,0.43],"promenade":[0.48,0.565]}}]}'::jsonb),'{originalLanguage}','"fr"'::jsonb) where id='proust';
commit;
select id,jsonb_array_length(metadata->'illustratedView'->'views') as panorama_count from public.books where id='proust';
